// Os bytes de quem chama ficam onde estão; o código nativo os lê no lugar.
const bytes = new Uint8Array(16 * 1024 * 1024);
const hash = native.checksum(bytes);   // uma chamada, nenhuma cópia

// O WebAssembly não lê um array JS no lugar: é preciso copiá-lo para a memória linear.
const ptr = wasm.alloc(data.byteLength);
new Int32Array(wasm.memory.buffer, ptr, data.length).set(data);   // a cada chamada
const sum = wasm.sum_i32(ptr, data.length);

// O código nativo constrói um objeto JS por linha, 10.000 vezes.
const rows = native.query(sql);         // [{ id, score, active, name }, …]

// Empacotado: volta um buffer, decodificado em objetos no JS.
const packed = native.queryPacked(sql);
